  ('diabetes',
   'Type 2 Diabetes',
   'Diabetes',
   '2026.1',
   'Glycemic control toward an individualized A1C goal, hypoglycemia prevention and routine complication screening for adults with type 2 diabetes.',
   ARRAY['ADA Standards of Care in Diabetes (2026)'],
   '{"goals":[{"title":"Improve A1C control"},{"title":"Maintain glucose within target range"},{"title":"Reduce episodes of hypoglycemia"},{"title":"Monitor blood glucose consistently"},{"title":"Improve diabetes medication adherence"},{"title":"Complete routine diabetes monitoring"},{"title":"Improve renal risk monitoring"}],"interventions":[{"title":"Diabetes education","goalTitle":"Improve A1C control"},{"title":"A1C follow-up","goalTitle":"Improve A1C control"},{"title":"Diabetes nutrition coaching","goalTitle":"Improve A1C control"},{"title":"Glucose monitoring support","goalTitle":"Monitor blood glucose consistently"},{"title":"Glucose pattern review","goalTitle":"Maintain glucose within target range"},{"title":"Hypoglycemia education","goalTitle":"Reduce episodes of hypoglycemia"},{"title":"Hypoglycemia review","goalTitle":"Reduce episodes of hypoglycemia"},{"title":"Medication adherence education","goalTitle":"Improve diabetes medication adherence"},{"title":"Diabetes monitoring checklist","goalTitle":"Complete routine diabetes monitoring"},{"title":"Renal monitoring","goalTitle":"Improve renal risk monitoring"}],"barriers":[{"title":"Limited progress toward A1C target","goalTitles":["Improve A1C control"]},{"title":"Diabetes self-management complexity","goalTitles":["Improve A1C control","Monitor blood glucose consistently"]},{"title":"Glucose-monitoring difficulty","goalTitles":["Monitor blood glucose consistently"]},{"title":"Hypoglycemia risk","goalTitles":["Reduce episodes of hypoglycemia"]},{"title":"Medication adherence difficulty","goalTitles":["Improve diabetes medication adherence"]},{"title":"Lab access issue","goalTitles":["Complete routine diabetes monitoring","Improve renal risk monitoring"]}]}'::jsonb,
   '{"thresholds":[{"measure":"A1C","comparator":"<","value":7,"unit":"%","label":"Goal for most nonpregnant adults","action":"Individualize: a less stringent goal (such as < 8%) fits limited life expectancy or high hypoglycemia risk.","source":"ADA Standards of Care in Diabetes (2026)"},{"measure":"A1C","comparator":">=","value":9,"unit":"%","label":"Well above goal","action":"Flag to the treating clinician for treatment review and step up outreach.","source":"Fold care-management practice"},{"measure":"CGM time in range (70–180 mg/dL)","comparator":">","value":70,"unit":"%","label":"Goal for most adults using CGM","source":"ADA Standards of Care in Diabetes (2026)"},{"measure":"Blood glucose","comparator":"<","value":70,"unit":"mg/dL","label":"Level 1 hypoglycemia","action":"Treat with 15 g fast-acting carbohydrate, recheck in 15 minutes, log the event.","source":"ADA Standards of Care in Diabetes (2026)"},{"measure":"Blood glucose","comparator":"<","value":54,"unit":"mg/dL","label":"Level 2 hypoglycemia","action":"Same-day notice to the treating clinician; review glucose-lowering medicines.","source":"ADA Standards of Care in Diabetes (2026)"},{"measure":"Blood pressure","comparator":"<","value":130,"unit":"mmHg systolic (and < 80 diastolic)","label":"BP goal in diabetes","source":"ADA Standards of Care in Diabetes (2026)"},{"measure":"Urine albumin-to-creatinine ratio","comparator":">=","value":30,"unit":"mg/g","label":"Albuminuria","action":"Follow the Chronic Kidney Disease pathway alongside this one.","source":"ADA Standards of Care in Diabetes (2026)"}],"decisionRules":[{"when":"A1C is above the individualized goal at a scheduled check","then":"Notify the treating clinician for treatment intensification review (avoid therapeutic inertia), recheck A1C in 3 months and move check-ins to every 2 weeks until the plan is updated.","source":"ADA Standards of Care in Diabetes (2026)"},{"when":"Level 2 or level 3 (severe) hypoglycemia is reported","then":"Notify the treating clinician the same day, review insulin and sulfonylurea use, and confirm glucagon is prescribed and the household knows how to use it.","source":"ADA Standards of Care in Diabetes (2026)"},{"when":"eGFR < 60 mL/min/1.73m² or urine albumin-to-creatinine ratio ≥ 30 mg/g","then":"Flag for clinician review of kidney-protective therapy (SGLT2 inhibitor and ACE inhibitor or ARB) and start the Chronic Kidney Disease pathway.","source":"ADA Standards of Care in Diabetes (2026)"},{"when":"A1C is at goal on two consecutive checks with a stable regimen","then":"Space A1C to every 6 months and check-ins to monthly.","source":"ADA Standards of Care in Diabetes (2026)"}]}'::jsonb,
   '[{"activity":"A1C","kind":"lab","times":1,"every":3,"unit":"month","appliesWhen":"Not at goal or therapy changed","source":"ADA Standards of Care in Diabetes (2026)"},{"activity":"A1C","kind":"lab","times":1,"every":6,"unit":"month","appliesWhen":"At goal with a stable regimen","source":"ADA Standards of Care in Diabetes (2026)"},{"activity":"Urine albumin-to-creatinine ratio and eGFR","kind":"lab","times":1,"every":1,"unit":"year","source":"ADA Standards of Care in Diabetes (2026)"},{"activity":"Comprehensive foot exam","kind":"visit","times":1,"every":1,"unit":"year","source":"ADA Standards of Care in Diabetes (2026)"},{"activity":"Dilated eye exam","kind":"visit","times":1,"every":1,"unit":"year","appliesWhen":"Every 1–2 years when there is no retinopathy and glycemia is at goal","source":"ADA Standards of Care in Diabetes (2026)"},{"activity":"Care-manager check-in","kind":"check_in","times":1,"every":1,"unit":"month","source":"Fold care-management practice"}]'::jsonb,
