  ('heart-failure',
   'Heart Failure',
   'Heart failure',
   '2026.1',
   'Daily self-monitoring, early recognition of decompensation, guideline-directed medical therapy follow-through and early follow-up after a hospital stay.',
   ARRAY['2022 AHA/ACC/HFSA Guideline for the Management of Heart Failure', 'AHA heart failure self-care guidance'],
   '{"goals":[{"title":"Improve heart failure symptom control"},{"title":"Monitor daily weight for heart failure"},{"title":"Improve recognition of warning signs"},{"title":"Maintain sodium consumption"},{"title":"Improve overall medication adherence"},{"title":"Complete post-discharge follow-up"},{"title":"Prevent avoidable readmission"}],"interventions":[{"title":"Daily weight monitoring","goalTitle":"Monitor daily weight for heart failure"},{"title":"Heart-failure symptom review","goalTitle":"Improve heart failure symptom control"},{"title":"Escalation coordination","goalTitle":"Improve heart failure symptom control"},{"title":"Warning-sign education","goalTitle":"Improve recognition of warning signs"},{"title":"Nutrition risk counseling","goalTitle":"Maintain sodium consumption"},{"title":"Medication adherence education","goalTitle":"Improve overall medication adherence"},{"title":"Refill support","goalTitle":"Improve overall medication adherence"},{"title":"Medication review","goalTitle":"Improve overall medication adherence"},{"title":"Post-discharge outreach","goalTitle":"Complete post-discharge follow-up"},{"title":"Readmission-risk review","goalTitle":"Prevent avoidable readmission"}],"barriers":[{"title":"Weight-monitoring inconsistency","goalTitles":["Monitor daily weight for heart failure"]},{"title":"Scale or equipment access","goalTitles":["Monitor daily weight for heart failure"]},{"title":"Difficulty recognizing cardiac symptoms","goalTitles":["Improve recognition of warning signs","Improve heart failure symptom control"]},{"title":"Difficulty following fluid/sodium plan","goalTitles":["Maintain sodium consumption"]},{"title":"Medication adherence difficulty","goalTitles":["Improve overall medication adherence"]},{"title":"High readmission risk","goalTitles":["Prevent avoidable readmission"]}]}'::jsonb,
   '{"thresholds":[{"measure":"Weight gain in 24 hours","comparator":">","value":2,"unit":"lb","label":"Possible fluid retention","action":"Same-day call to the care team; notify the heart failure clinician.","source":"AHA heart failure self-care guidance"},{"measure":"Weight gain in 7 days","comparator":">","value":5,"unit":"lb","label":"Possible fluid retention","action":"Same-day call to the care team; notify the heart failure clinician.","source":"AHA heart failure self-care guidance"},{"measure":"Systolic blood pressure","comparator":"<","value":90,"unit":"mmHg","label":"Low with symptoms","action":"If dizzy or lightheaded, notify the clinician the same day before the next dose.","source":"Fold care-management practice"},{"measure":"Resting heart rate","comparator":">","value":100,"unit":"bpm","label":"Tachycardia","action":"Ask about symptoms and notify the clinician the same day.","source":"Fold care-management practice"}],"decisionRules":[{"when":"Chest pain, severe shortness of breath, fainting or confusion","then":"Direct the patient to call 911.","source":"Fold care-management practice"},{"when":"Worsening breathlessness, orthopnea, new or increased swelling, or a weight-gain threshold is crossed","then":"Notify the heart failure clinician the same day and follow their diuretic instructions; recheck symptoms within 48 hours.","source":"AHA heart failure self-care guidance"},{"when":"Discharged after a heart failure hospital stay","then":"Schedule a clinician follow-up within 7 days, reconcile medicines and move check-ins to weekly for 30 days.","source":"2022 AHA/ACC/HFSA Guideline for the Management of Heart Failure"},{"when":"Reduced ejection fraction (HFrEF) and not on all four medicine classes (ARNI/ACE inhibitor/ARB, evidence-based beta blocker, MRA, SGLT2 inhibitor)","then":"Flag to the treating clinician for guideline-directed therapy review.","source":"2022 AHA/ACC/HFSA Guideline for the Management of Heart Failure"}]}'::jsonb,
   '[{"activity":"Weight, before breakfast after voiding","kind":"measurement","times":1,"every":1,"unit":"day","source":"AHA heart failure self-care guidance"},{"activity":"Symptom check-in","kind":"check_in","times":1,"every":1,"unit":"week","appliesWhen":"First 30 days after discharge or a medicine change","source":"Fold care-management practice"},{"activity":"Symptom check-in","kind":"check_in","times":1,"every":1,"unit":"month","appliesWhen":"Stable","source":"Fold care-management practice"},{"activity":"Potassium and kidney function","kind":"lab","times":1,"every":1,"unit":"week","appliesWhen":"Within 1 week of starting or changing an ACE inhibitor, ARB, ARNI or MRA","source":"2022 AHA/ACC/HFSA Guideline for the Management of Heart Failure"},{"activity":"Medication review","kind":"medication_review","times":1,"every":3,"unit":"month","source":"Fold care-management practice"}]'::jsonb,
