  ('copd',
   'COPD',
   'COPD',
   '2026.1',
   'Symptom and exacerbation control through inhaler technique, a written action plan, tobacco cessation, oxygen where indicated and vaccination.',
   ARRAY['GOLD Report (2025)'],
   '{"goals":[{"title":"Improve COPD symptom control"},{"title":"Reduce respiratory exacerbations"},{"title":"Improve inhaler technique"},{"title":"Improve inhaler adherence"},{"title":"Monitor oxygen saturation for COPD"},{"title":"Reduce tobacco exposure"},{"title":"Complete immunization review"}],"interventions":[{"title":"Respiratory symptom monitoring","goalTitle":"Improve COPD symptom control"},{"title":"Respiratory action-plan education","goalTitle":"Reduce respiratory exacerbations"},{"title":"Exacerbation prevention","goalTitle":"Reduce respiratory exacerbations"},{"title":"Inhaler education","goalTitle":"Improve inhaler technique"},{"title":"Inhaler teach-back","goalTitle":"Improve inhaler technique"},{"title":"Medication adherence education","goalTitle":"Improve inhaler adherence"},{"title":"Oxygen-use support","goalTitle":"Monitor oxygen saturation for COPD"},{"title":"Tobacco-use counseling","goalTitle":"Reduce tobacco exposure"},{"title":"Tobacco cessation resources","goalTitle":"Reduce tobacco exposure"},{"title":"Immunization review","goalTitle":"Complete immunization review"}],"barriers":[{"title":"Respiratory symptom burden","goalTitles":["Improve COPD symptom control"]},{"title":"Difficulty following action plan","goalTitles":["Reduce respiratory exacerbations"]},{"title":"Incorrect inhaler technique","goalTitles":["Improve inhaler technique"]},{"title":"Inhaler adherence difficulty","goalTitles":["Improve inhaler adherence"]},{"title":"Oxygen equipment issue","goalTitles":["Monitor oxygen saturation for COPD"]},{"title":"Tobacco cessation difficulty","goalTitles":["Reduce tobacco exposure"]}]}'::jsonb,
   '{"thresholds":[{"measure":"Resting SpO2","comparator":"<=","value":88,"unit":"%","label":"Severe resting hypoxemia","action":"Flag to the clinician for long-term oxygen evaluation (confirm with arterial blood gas).","source":"GOLD Report (2025)"},{"measure":"SpO2 on supplemental oxygen","comparator":"between","value":88,"value2":92,"unit":"%","label":"Target range","source":"GOLD Report (2025)"},{"measure":"COPD Assessment Test (CAT)","comparator":">=","value":10,"unit":"points","label":"High symptom burden","action":"Review inhaler regimen and technique with the clinician.","source":"GOLD Report (2025)"},{"measure":"Moderate or severe exacerbations in 12 months","comparator":">=","value":2,"label":"High exacerbation risk","action":"Flag for clinician review of maintenance therapy; one exacerbation leading to a hospital stay counts the same.","source":"GOLD Report (2025)"}],"decisionRules":[{"when":"More breathlessness, more sputum or a change in sputum color","then":"Start the written action plan and notify the clinician the same day.","source":"GOLD Report (2025)"},{"when":"Severe breathlessness at rest, confusion or blue lips","then":"Direct the patient to call 911.","source":"Fold care-management practice"},{"when":"Discharged after an exacerbation hospital stay","then":"Schedule follow-up within 30 days, re-check inhaler technique, and refer to pulmonary rehabilitation.","source":"GOLD Report (2025)"},{"when":"The patient smokes","then":"Offer cessation counseling and pharmacotherapy referral at every contact.","source":"GOLD Report (2025)"}]}'::jsonb,
   '[{"activity":"Inhaler technique teach-back","kind":"check_in","times":1,"every":3,"unit":"month","appliesWhen":"And at every inhaler change","source":"GOLD Report (2025)"},{"activity":"Symptom score (CAT or mMRC)","kind":"measurement","times":1,"every":3,"unit":"month","source":"Fold care-management practice"},{"activity":"Spirometry","kind":"lab","times":1,"every":1,"unit":"year","source":"GOLD Report (2025)"},{"activity":"Immunization review (influenza, RSV, pneumococcal, COVID-19)","kind":"other","times":1,"every":1,"unit":"year","source":"GOLD Report (2025)"},{"activity":"Care-manager check-in","kind":"check_in","times":1,"every":1,"unit":"month","source":"Fold care-management practice"}]'::jsonb,
