   'Risk-based kidney monitoring, blood pressure control, kidney-protective therapy review, safe medicine use and timely nephrology referral.',
   ARRAY['KDIGO 2024 Clinical Practice Guideline for CKD', 'KDIGO 2021 Guideline for Blood Pressure in CKD'],
   '{"goals":[{"title":"Maintain kidney function monitoring"},{"title":"Maintain individualized renal-protection plan"},{"title":"Maintain blood pressure within target"},{"title":"Improve overall medication adherence"},{"title":"Improve completion of recommended labs"},{"title":"Improve understanding of condition"}],"interventions":[{"title":"Lab tracking","goalTitle":"Maintain kidney function monitoring"},{"title":"Renal monitoring","goalTitle":"Maintain kidney function monitoring"},{"title":"Lab completion follow-up","goalTitle":"Improve completion of recommended labs"},{"title":"Renal risk-factor support","goalTitle":"Maintain individualized renal-protection plan"},{"title":"Medication review","goalTitle":"Maintain individualized renal-protection plan"},{"title":"Blood pressure monitoring","goalTitle":"Maintain blood pressure within target"},{"title":"Medication adherence education","goalTitle":"Improve overall medication adherence"},{"title":"Chronic kidney disease education","goalTitle":"Improve understanding of condition"}],"barriers":[{"title":"Kidney-monitoring complexity","goalTitles":["Maintain kidney function monitoring"]},{"title":"Lab access issue","goalTitles":["Improve completion of recommended labs"]},{"title":"Polypharmacy","goalTitles":["Maintain individualized renal-protection plan"]},{"title":"Difficulty controlling condition","goalTitles":["Maintain blood pressure within target"]},{"title":"Medication adherence difficulty","goalTitles":["Improve overall medication adherence"]},{"title":"Limited health literacy","goalTitles":["Improve understanding of condition"]}]}'::jsonb,
   '{"thresholds":[{"measure":"eGFR","comparator":"<","value":60,"unit":"mL/min/1.73m²","label":"CKD G3a or worse when present 3 months or more","source":"KDIGO 2024 Clinical Practice Guideline for CKD"},{"measure":"Urine albumin-to-creatinine ratio","comparator":">=","value":30,"unit":"mg/g","label":"Moderately increased albuminuria (A2)","source":"KDIGO 2024 Clinical Practice Guideline for CKD"},{"measure":"eGFR","comparator":"<","value":30,"unit":"mL/min/1.73m²","label":"G4 to G5","action":"Refer to nephrology.","source":"KDIGO 2024 Clinical Practice Guideline for CKD"},{"measure":"Urine albumin-to-creatinine ratio","comparator":">=","value":300,"unit":"mg/g","label":"Severely increased albuminuria (A3)","action":"Refer to nephrology.","source":"KDIGO 2024 Clinical Practice Guideline for CKD"},{"measure":"Systolic blood pressure","comparator":"<","value":120,"unit":"mmHg","label":"Goal when tolerated (standardized office reading)","source":"KDIGO 2021 Guideline for Blood Pressure in CKD"}],"decisionRules":[{"when":"eGFR falls 25% or more from baseline, or progression is rapid","then":"Notify the treating clinician and refer to nephrology.","source":"KDIGO 2024 Clinical Practice Guideline for CKD"},{"when":"eGFR ≥ 20 and type 2 diabetes, heart failure, or urine albumin-to-creatinine ratio ≥ 200 mg/g","then":"Flag for clinician review of SGLT2 inhibitor therapy.","source":"KDIGO 2024 Clinical Practice Guideline for CKD"},{"when":"Albuminuria and an ACE inhibitor or ARB is started or the dose changes","then":"Check potassium and creatinine within 2–4 weeks.","source":"KDIGO 2024 Clinical Practice Guideline for CKD"},{"when":"A new medicine is started or an over-the-counter NSAID is in use","then":"Medication review for kidney dosing and nephrotoxic drugs; tell the patient to avoid NSAIDs unless the clinician approves.","source":"KDIGO 2024 Clinical Practice Guideline for CKD"}]}'::jsonb,
   '[{"activity":"eGFR and urine albumin-to-creatinine ratio","kind":"lab","times":1,"every":1,"unit":"year","appliesWhen":"Low risk: G1–G2 with A1","source":"KDIGO 2024 Clinical Practice Guideline for CKD"},{"activity":"eGFR and urine albumin-to-creatinine ratio","kind":"lab","times":2,"every":1,"unit":"year","appliesWhen":"Moderate risk: G3a or A2","source":"KDIGO 2024 Clinical Practice Guideline for CKD"},{"activity":"eGFR and urine albumin-to-creatinine ratio","kind":"lab","times":3,"every":1,"unit":"year","appliesWhen":"High risk: G3b or worse, or A3 (4 or more a year at very high risk)","source":"KDIGO 2024 Clinical Practice Guideline for CKD"},{"activity":"Medication review","kind":"medication_review","times":1,"every":6,"unit":"month","source":"Fold care-management practice"},{"activity":"Care-manager check-in","kind":"check_in","times":1,"every":1,"unit":"month","source":"Fold care-management practice"}]'::jsonb,
