   '{"thresholds":[{"measure":"Blood pressure","comparator":"<","value":130,"unit":"mmHg systolic (and < 80 diastolic)","label":"Goal for most adults","action":"Encourage systolic < 120 when tolerated.","source":"2025 AHA/ACC Guideline for High Blood Pressure in Adults"},{"measure":"Blood pressure","comparator":">=","value":140,"unit":"mmHg systolic (or ≥ 90 diastolic)","label":"Stage 2","action":"Flag to the treating clinician if not already on a plan to reach goal.","source":"2025 AHA/ACC Guideline for High Blood Pressure in Adults"},{"measure":"Blood pressure","comparator":">","value":180,"unit":"mmHg systolic (or > 120 diastolic)","label":"Severe","action":"Recheck after 5 minutes of rest; with chest pain, shortness of breath, weakness, vision or speech change call 911; without symptoms notify the clinician the same day.","source":"2025 AHA/ACC Guideline for High Blood Pressure in Adults"}],"decisionRules":[{"when":"A blood pressure medicine is started or changed","then":"Monthly follow-up until blood pressure is at goal.","source":"2025 AHA/ACC Guideline for High Blood Pressure in Adults"},{"when":"Home average is above goal for 2 consecutive reviews","then":"Check cuff technique and adherence first, then flag to the treating clinician for treatment review.","source":"Fold care-management practice"},{"when":"Above goal on 3 or more medicines including a diuretic","then":"Flag for resistant hypertension evaluation, including screening for primary aldosteronism.","source":"2025 AHA/ACC Guideline for High Blood Pressure in Adults"},{"when":"Blood pressure is at goal on 2 consecutive reviews","then":"Space check-ins to every 3 months.","source":"2025 AHA/ACC Guideline for High Blood Pressure in Adults"}]}'::jsonb,
   '[{"activity":"Home blood pressure (2 readings, morning and evening)","kind":"measurement","times":2,"every":1,"unit":"day","appliesWhen":"For the 7 days before each review, or daily while medicines are being adjusted","source":"2025 AHA/ACC Guideline for High Blood Pressure in Adults"},{"activity":"Care-manager check-in","kind":"check_in","times":1,"every":1,"unit":"month","appliesWhen":"Until at goal","source":"2025 AHA/ACC Guideline for High Blood Pressure in Adults"},{"activity":"Care-manager check-in","kind":"check_in","times":1,"every":3,"unit":"month","appliesWhen":"At goal","source":"2025 AHA/ACC Guideline for High Blood Pressure in Adults"},{"activity":"Basic metabolic panel (potassium, creatinine)","kind":"lab","times":1,"every":1,"unit":"year","appliesWhen":"And 2–4 weeks after starting or changing a diuretic, ACE inhibitor or ARB","source":"Fold care-management practice"}]'::jsonb,
