   'Risk-based statin therapy follow-through, LDL-C response checks, side-effect support and heart-healthy lifestyle.',
   ARRAY['2018 AHA/ACC Guideline on the Management of Blood Cholesterol'],
   '{"goals":[{"title":"Improve lipid management"},{"title":"Improve overall medication adherence"},{"title":"Reduce saturated fat intake"},{"title":"Reduce cardiovascular risk through activity"},{"title":"Improve weight management"}],"interventions":[{"title":"Lipid-management follow-up","goalTitle":"Improve lipid management"},{"title":"Lab tracking","goalTitle":"Improve lipid management"},{"title":"Medication adherence education","goalTitle":"Improve overall medication adherence"},{"title":"Refill support","goalTitle":"Improve overall medication adherence"},{"title":"Nutrition coaching","goalTitle":"Reduce saturated fat intake"},{"title":"Activity plan","goalTitle":"Reduce cardiovascular risk through activity"},{"title":"Activity coaching","goalTitle":"Reduce cardiovascular risk through activity"},{"title":"Weight-management coaching","goalTitle":"Improve weight management"}],"barriers":[{"title":"Limited understanding of lipid management","goalTitles":["Improve lipid management"]},{"title":"Medication side effects","goalTitles":["Improve overall medication adherence"]},{"title":"Medication adherence difficulty","goalTitles":["Improve overall medication adherence"]},{"title":"Nutrition challenges","goalTitles":["Reduce saturated fat intake"]},{"title":"Limited physical activity","goalTitles":["Reduce cardiovascular risk through activity"]},{"title":"Weight-management difficulty","goalTitles":["Improve weight management"]}]}'::jsonb,
   '{"thresholds":[{"measure":"LDL-C","comparator":">=","value":190,"unit":"mg/dL","label":"Severe hypercholesterolemia","action":"Flag for high-intensity statin review (ages 20–75).","source":"2018 AHA/ACC Guideline on the Management of Blood Cholesterol"},{"measure":"LDL-C on maximally tolerated statin, with clinical ASCVD","comparator":">=","value":70,"unit":"mg/dL","label":"Very high risk above threshold","action":"Flag for clinician review of adding a non-statin (such as ezetimibe).","source":"2018 AHA/ACC Guideline on the Management of Blood Cholesterol"},{"measure":"10-year ASCVD risk","comparator":">=","value":7.5,"unit":"%","label":"Intermediate or higher risk","action":"Prompt a statin discussion with the clinician if not on one.","source":"2018 AHA/ACC Guideline on the Management of Blood Cholesterol"},{"measure":"Triglycerides (fasting)","comparator":">=","value":500,"unit":"mg/dL","label":"Severe hypertriglyceridemia","action":"Flag to the clinician the same week.","source":"2018 AHA/ACC Guideline on the Management of Blood Cholesterol"}],"decisionRules":[{"when":"Diabetes, age 40–75, and not on a statin","then":"Flag for moderate-intensity statin review regardless of estimated risk.","source":"2018 AHA/ACC Guideline on the Management of Blood Cholesterol"},{"when":"LDL-C falls less than expected after a statin start or change (under 50% on high-intensity, 30–49% on moderate-intensity)","then":"Review adherence first, then flag to the treating clinician for intensification review.","source":"2018 AHA/ACC Guideline on the Management of Blood Cholesterol"},{"when":"Muscle aches or weakness on a statin","then":"Ask the patient not to stop on their own; notify the clinician to assess statin-associated muscle symptoms.","source":"2018 AHA/ACC Guideline on the Management of Blood Cholesterol"}]}'::jsonb,
   '[{"activity":"Lipid panel","kind":"lab","times":1,"every":3,"unit":"month","appliesWhen":"4–12 weeks after starting or changing lipid therapy","source":"2018 AHA/ACC Guideline on the Management of Blood Cholesterol"},{"activity":"Lipid panel","kind":"lab","times":1,"every":1,"unit":"year","appliesWhen":"Stable on therapy (every 3–12 months as needed)","source":"2018 AHA/ACC Guideline on the Management of Blood Cholesterol"},{"activity":"Adherence and refill check","kind":"medication_review","times":1,"every":1,"unit":"month","source":"Fold care-management practice"},{"activity":"Lifestyle coaching check-in","kind":"check_in","times":1,"every":1,"unit":"month","source":"Fold care-management practice"}]'::jsonb,
